'use client';

import React from 'react';
import styled from 'styled-components';
import CmsPopup from '@/components/CmsPopup';

// 스타일 컴포넌트들
const AlertContainer = styled.div<{ type: 'success' | 'error' | 'warning' }>`
  padding: 20px;
  max-width: 500px;

  .alert-icon {
    font-size: 24px;
    margin-bottom: 15px;
    text-align: center;
  }

  .alert-message {
    white-space: pre-line;
    line-height: 1.5;
    color: ${props => {
      switch (props.type) {
        case 'success': return '#155724';
        case 'error': return '#721c24';
        case 'warning': return '#856404';
        default: return '#333';
      }
    }};
  }

  .alert-buttons {
    display: flex;
    justify-content: center;
    margin-top: 20px;
  }
`;

const ActionButton = styled.button<{ variant?: 'primary' | 'secondary' }>`
  padding: 10px 20px;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-weight: bold;

  background: ${props => props.variant === 'primary' ? '#007bff' : '#6c757d'};
  color: white;

  &:hover {
    background: ${props => props.variant === 'primary' ? '#0056b3' : '#545b62'};
  }

  &:disabled {
    background: #ccc;
    cursor: not-allowed;
  }
`;

// Props 타입 정의
interface UploadResultPopupProps {
  isOpen: boolean;
  onClose: () => void;
  type: 'success' | 'error' | 'warning';
  message: string;
}

const UploadResultPopup: React.FC<UploadResultPopupProps> = ({
  isOpen,
  onClose,
  type,
  message
}) => {
  const getTitle = () => {
    switch (type) {
      case 'success': return '성공';
      case 'warning': return '경고';
      case 'error': return '오류';
      default: return '알림';
    }
  };

  const getIcon = () => {
    switch (type) {
      case 'success': return '✅';
      case 'warning': return '⚠️';
      case 'error': return '❌';
      default: return 'ℹ️';
    }
  };

  return (
    <CmsPopup 
      title={getTitle()} 
      isOpen={isOpen} 
      onClose={onClose}
    >
      <AlertContainer type={type}>
        <div className="alert-icon">
          {getIcon()}
        </div>
        <div className="alert-message">
          {message}
        </div>
        <div className="alert-buttons">
          <ActionButton variant="primary" onClick={onClose}>
            확인
          </ActionButton>
        </div>
      </AlertContainer>
    </CmsPopup>
  );
};

export default UploadResultPopup;
